// Helper functions
function getFamilyMembers(characterUid) {
  return FAMILY_BY_UID[characterUid] || [];
}

function getRelationshipsByType(characterUid, relationshipType) {
  const family = getFamilyMembers(characterUid);
  return family
    .filter(rel => rel.relationship === relationshipType)
    .map(rel => rel.related_uid);
}

function getExtendedFamily(characterUid) {
  const family = getFamilyMembers(characterUid);
  const extendedTypes = ['grandparent', 'grandchild', 'uncle', 'aunt', 'nephew', 'niece', 'cousin'];
  return family.filter(rel => extendedTypes.includes(rel.relationship));
}

// Convert an Excel-style full ID into the UID used by FAMILY_BY_UID.
// - Full ID: template:campaign_name:campaign_key:faction:faction_id:template_id
// - Lua/template-only: template
function getCharacterUid(idOrTemplate) {
  if (!idOrTemplate) return null;
  const s = String(idOrTemplate);
  if (s.includes(':')) {
    const parts = s.split(':');
    if (parts.length >= 6) return String(parts[5]).trim();
    return String(parts[0]).trim();
  }
  return s.trim();
}
